mapper.select:


    m.deleted = 0

        AND m.dept_id = #{scopeDeptId}



            AND m.dept_id = #{q.deptId}


            AND m.status = #{q.status}


            AND m.mentor_name LIKE CONCAT('%', #{q.mentorName}, '%')


            AND m.mentor_phone LIKE CONCAT('%', #{q.mentorPhone}, '%')


            AND (m.mentor_name LIKE CONCAT('%', #{q.keyword}, '%')
                 OR m.mentor_phone LIKE CONCAT('%', #{q.keyword}, '%'))



ORDER BY m.status ASC, m.dept_id ASC, m.id ASC
